	pr, pw, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { pr.Close() })
	go func() {
		// The form reads one line; provide a unique name so it exits the loop.
		pw.Write([]byte("unique-test-repo\n")) //nolint:errcheck // test helper
		pw.Close()
	}()
	oldStdin := os.Stdin
	os.Stdin = pr
	t.Cleanup(func() { os.Stdin = oldStdin })

	dir := t.TempDir()
	restoreCwd(t, dir)

